+++ b/scripts/dist-dom-globals.mjs
@@ -0,0 +1,21 @@
+/**
+ * Some package entries are client-only: @prometheus-ags/a2ui-react's root entry
+ * defines the official A2UI 1.0 basic catalog as Custom Elements when it loads
+ * (`class … extends HTMLElement`), so plain Node cannot import it. The export
+ * ledger scripts only read export names, so for those packages they import the
+ * dist inside a jsdom window. Other packages keep the plain Node environment.
+ */
+import { JSDOM } from "jsdom";
+
+const CLIENT_ONLY_PACKAGES = new Set(["a2ui-react"]);
+
+/** Installs window/document/HTMLElement/customElements globals once, for client-only packages. */
+export function installDomGlobalsFor(directory) {
+  if (!CLIENT_ONLY_PACKAGES.has(directory) || typeof globalThis.HTMLElement !== "undefined") return;
+  const { window } = new JSDOM("<!doctype html><html><body></body></html>", { url: "http://localhost/" });
+  for (const name of ["window", "document", "HTMLElement", "customElements", "Node", "Element", "CustomEvent", "Event", "MutationObserver", "getComputedStyle"]) {
+    if (!(name in globalThis)) {
+      Object.defineProperty(globalThis, name, { value: name === "window" ? window : window[name], configurable: true, writable: true });
+    }
+  }
+}
